def quote_json(w:mutbuf, start:u64, size:u64, target:u64) -> u64:
    at = target
    store(w, at, 34)
    at = at + 1
    i = 0
    while i < size:
        ch = byte(w, start + i)
        if ch == 34 or ch == 92:
            store(w, at, 92)
            store(w, at + 1, ch)
            at = at + 2
        elif ch == 8 or ch == 9 or ch == 10 or ch == 12 or ch == 13:
