CONSTANTS = {'MAGIC': MAGIC, 'INPUT_BYTES': INPUT_BYTES, 'O_BYTES': OUTPUT_BYTES,
    'W_BYTES': WORKSPACE_BYTES, 'S': 4096, 'T': 8192, 'TO': 4202496,
    'V': 8396800, 'VF': 10493952, 'FS': 12591104, 'HEAP': 12607488,
