    if tag(w, node) != 2 or size_of(w, node) == 0:
        return False
    index = 0
    number = 0
    while index < size_of(w, node):
        digit = byte(w, node + 16 + index)
        if digit < 48 or digit > 57:
            return False
        digit = digit - 48
        if number > maximum // 10 or (number == maximum // 10 and digit > maximum % 10):
